// Python runner for the codefix bed.
// - runTrusted(): host-generated reference/mutant modules (trusted, generated by this bed).
// - runSandboxed(): untrusted candidate sources. Runs only inside a fresh user+net+mount
//   namespace (unshare --user --map-root-user --net --mount --fork --kill-child) with tmpfs
//   over /home, /root, /opt/models and /tmp, the root filesystem remounted read-only when the
//   kernel allows it, rlimits, a wall timeout, and JSON over stdin/stdout. If the sandbox
//   cannot be set up, the call fails closed ({ ok: false }).
import { spawnSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const PYTHON = '/usr/bin/python3';
const HARNESS = readFileSync(fileURLToPath(new URL('./harness.py', import.meta.url)), 'utf8');
const MARK = '@@CODEFIX-RESULT@@';
// -P -s -S -B instead of -I so that PYTHONHASHSEED (set here, the environment is otherwise
// empty) applies: set iteration order must not make results nondeterministic.
const MIN_ENV = { PATH: '/usr/bin:/bin', LANG: 'C.UTF-8', PYTHONHASHSEED: '0', PYTHONDONTWRITEBYTECODE: '1' };

const SANDBOX_SCRIPT = [
  'set -e',
  'mount -t tmpfs -o size=8m,mode=0755 tmpfs /home',
  'mount -t tmpfs -o size=8m,mode=0700 tmpfs /root',
  'if [ -d /opt/models ]; then mount -t tmpfs -o size=1m,mode=0755 tmpfs /opt/models; fi',
  'mount -t tmpfs -o size=16m,mode=1777 tmpfs /tmp',
  'mount -o remount,bind,ro / 2>/dev/null || true',
  'cd /tmp',
  'ulimit -v 1048576',
  'ulimit -f 4096',
  'ulimit -t "$3"',
  'exec timeout -s KILL "$2" /usr/bin/python3 -P -s -S -B -c "$1"',
].join('\n');

function parse(proc, label, nonce) {
  if (proc.error) return { ok: false, error: `${label}: ${proc.error.code || proc.error.message}` };
  const out = String(proc.stdout || '');
  const mark = MARK + nonce;
  const idx = out.lastIndexOf(mark);
  if (idx < 0) {
    const why = proc.signal ? `killed by ${proc.signal}` : `exit ${proc.status}`;
    return { ok: false, error: `${label}: no result (${why}); stderr: ${String(proc.stderr || '').slice(-400)}` };
  }
  try {
    return { ok: true, value: JSON.parse(out.slice(idx + mark.length).split('\n')[0]) };
  } catch (e) {
    return { ok: false, error: `${label}: unparseable result (${e.message})` };
  }
}

export function pythonAvailable() { return existsSync(PYTHON); }

// Trusted runs execute only bed-generated modules, or merely parse (ast) untrusted source.
export function runTrusted(request, { timeoutMs = 20000 } = {}) {
  const proc = spawnSync(PYTHON, ['-P', '-s', '-S', '-B', '-c', HARNESS], {
    input: JSON.stringify(request), env: MIN_ENV, cwd: '/', timeout: timeoutMs, killSignal: 'SIGKILL',
    maxBuffer: 64 * 1024 * 1024, encoding: 'utf8',
  });
  return parse(proc, 'trusted python', '');
}

// The result marker carries a per-call random nonce, so text printed by the candidate cannot be
// mistaken for the harness result (the nonce never influences the result values).
export function runSandboxed(request, { timeoutMs = 1800 } = {}) {
  const seconds = Math.max(1, Math.ceil(timeoutMs / 1000));
  const nonce = randomBytes(12).toString('hex');
  const proc = spawnSync('unshare', ['--user', '--map-root-user', '--net', '--mount', '--fork', '--kill-child',
    'sh', '-c', SANDBOX_SCRIPT, 'codefix-sandbox', HARNESS, String(seconds), '8'], {
    input: JSON.stringify({ ...request, nonce }), env: MIN_ENV, cwd: '/', timeout: timeoutMs + 400, killSignal: 'SIGKILL',
    maxBuffer: 16 * 1024 * 1024, encoding: 'utf8',
  });
  return parse(proc, 'sandboxed python', nonce);
}

// Audit helper: run an arbitrary Python script (e.g. attacks/trivial_solver.py) in the same namespace
// sandbox with a JSON payload on stdin. Returns { ok, stdout, stderr, status }.
export function runScriptSandboxed(script, payload, { timeoutMs = 120000 } = {}) {
  const seconds = Math.max(1, Math.ceil(timeoutMs / 1000));
  const proc = spawnSync('unshare', ['--user', '--map-root-user', '--net', '--mount', '--fork', '--kill-child',
    'sh', '-c', SANDBOX_SCRIPT, 'codefix-sandbox', script, String(seconds), String(seconds + 5)], {
    input: JSON.stringify(payload), env: MIN_ENV, cwd: '/', timeout: timeoutMs + 2000, killSignal: 'SIGKILL',
    maxBuffer: 64 * 1024 * 1024, encoding: 'utf8',
  });
  return { ok: !proc.error && proc.status === 0, stdout: String(proc.stdout || ''), stderr: String(proc.stderr || ''), status: proc.status };
}
